import{a as e,c as t,i as n,l as r,n as i,o as a,r as o,s,t as c}from"./app-C0WnsF-Q.js";import"./storefront-bundle-catalog-DAv2LiNe.js";import"./bundle-optional-items-Z5g-bzEh.js";var l=JSON.parse(`{"path":"/product-bundle/pricing-and-discounts.html","title":"Pricing & Discounts","lang":"en-US","frontmatter":{"title":"Pricing & Discounts"},"git":{},"filePathRelative":"product-bundle/pricing-and-discounts.md"}`),u={name:`pricing-and-discounts.md`};function d(c,l,u,d,f,p){let m=t(`RouteLink`);return s(),o(`div`,null,[l[8]||=i(`h1`,{id:`pricing-discounts`,tabindex:`-1`},[i(`a`,{class:`header-anchor`,href:`#pricing-discounts`},[i(`span`,null,`Pricing & Discounts`)])],-1),i(`p`,null,[l[1]||=e(`The `,-1),l[2]||=i(`strong`,null,`Bundle Pricing Mode`,-1),l[3]||=e(` on the `,-1),a(m,{to:`/product-bundle/creating-a-bundle.html#step-2-configure-the-bundle-items-tab`},{default:r(()=>[...l[0]||=[e(`Bundle Items tab`,-1)]]),_:1}),l[4]||=e(` decides how the kit is priced. A bundle discount can be layered on top of either mode.`,-1)]),l[9]||=n(`<h2 id="fixed-bundle-price" tabindex="-1"><a class="header-anchor" href="#fixed-bundle-price"><span>Fixed Bundle Price</span></a></h2><p>The customer pays one flat price for the kit, no matter which optional items they select.</p><p><img src="/bundle-products-for-woocommerce/images/product-bundle/bundle-items-fixed-price.webp" alt="Fixed pricing mode configuration"></p><ul><li>Enter the price in <strong>Bundle Fixed Price</strong> (the field is visible only while fixed mode is selected).</li><li>If you leave it empty, the product&#39;s <strong>Regular price</strong> from the General tab is used. When you type a Regular price while the fixed-price field is empty, the editor copies it across for you.</li><li>On the storefront the product page and catalog show the price like any normal product — no per-item prices, no running total:</li></ul><p><img src="/bundle-products-for-woocommerce/images/product-bundle/bundle-fixed-price-page.webp" alt="A fixed-price bundle on the storefront"></p><div class="hint-container tip"><p class="hint-container-title">When to choose fixed mode</p><p>Use it for package deals with a strong headline price (&quot;The complete kit for $5,999&quot;), especially when optional extras shouldn&#39;t change the price. Note that optional items still get added to the kit for free when ticked — so in fixed mode most merchants keep <strong>all items mandatory</strong>.</p></div><h2 id="dynamic-bundle-price" tabindex="-1"><a class="header-anchor" href="#dynamic-bundle-price"><span>Dynamic Bundle Price</span></a></h2><p>The total is calculated from what the customer actually selects: the sum of each included item&#39;s price × its quantity, multiplied by the number of kits.</p><p>On the product page each item shows its line price, and a <strong>Bundle Total</strong> updates live as checkboxes are ticked:</p><p><img src="/bundle-products-for-woocommerce/images/product-bundle/bundle-optional-items.webp" alt="Dynamic bundle with optional items selected"></p><p>In the shop catalog a dynamic bundle is listed as &quot;<strong>From:</strong> …&quot; — the price of its <strong>mandatory items</strong> (with any discount applied), which is the minimum a customer can pay:</p><p><img src="/bundle-products-for-woocommerce/images/product-bundle/storefront-bundle-catalog.webp" alt="Dynamic bundle in the catalog with From price"></p><h2 id="bundle-discount" tabindex="-1"><a class="header-anchor" href="#bundle-discount"><span>Bundle discount</span></a></h2><p>Tick <strong>Enable Bundle Discount</strong> and two extra fields appear:</p><table><thead><tr><th>Field</th><th>Options</th></tr></thead><tbody><tr><td><strong>Discount Type</strong></td><td><strong>Percentage (%)</strong> — capped at 100%, or <strong>Fixed Amount</strong> — a currency amount</td></tr><tr><td><strong>Discount Value</strong></td><td>The number to subtract; the result never drops below zero</td></tr></tbody></table><p>The discount applies to the <strong>final bundle price</strong> in both modes:</p><ul><li><strong>Fixed mode:</strong> catalog and product page show the original price struck through next to the discounted price (e.g. <s>$6,000.00</s> $5,500.00).</li><li><strong>Dynamic mode:</strong> the product page shows the struck-through selection total, the discounted <strong>Bundle Total</strong> and a green &quot;<strong>You Save: $…</strong>&quot; note — all recalculated instantly when the selection or quantity changes.</li></ul><h2 id="worked-example-from-the-live-demo" tabindex="-1"><a class="header-anchor" href="#worked-example-from-the-live-demo"><span>Worked example (from the live demo)</span></a></h2><p>The demo&#39;s <em>Electronic Bundle Product</em> uses <strong>dynamic</strong> pricing, a <strong>10% discount</strong>, and Compulsory Items Count = 1:</p><table><thead><tr><th>Item</th><th>Price</th><th>Status</th></tr></thead><tbody><tr><td>Washing Machine</td><td>$1,300.00</td><td>Mandatory</td></tr><tr><td>Apple iPhone 14</td><td>$1,200.00</td><td>Optional</td></tr><tr><td>Apple MacBook Ai</td><td>$2,500.00</td><td>Optional</td></tr><tr><td>InfinityView LED TV</td><td>$1,500.00</td><td>Optional</td></tr></tbody></table><ul><li>Catalog price: &quot;<strong>From:</strong> <s>$1,300.00</s> <strong>$1,170.00</strong>&quot; (mandatory item minus 10%).</li><li>Washing Machine only: <s>$1,300</s> → <strong>$1,170</strong>, You Save $130.</li><li>With the iPhone ticked: $2,500 selection → <strong>$2,250</strong>, You Save $250.</li><li>With iPhone and MacBook ticked at quantity 2: $10,000 → <strong>$9,000</strong>, You Save $1,000.</li></ul>`,21),i(`p`,null,[l[6]||=e(`The same discounted price is recalculated server-side in the cart, so page tricks can't change what is actually charged. Continue with `,-1),a(m,{to:`/product-bundle/stock-quantity-limits.html`},{default:r(()=>[...l[5]||=[e(`Stock, Quantity & Limits`,-1)]]),_:1}),l[7]||=e(`.`,-1)]),l[10]||=i(`div`,{class:`hint-container warning`},[i(`p`,{class:`hint-container-title`},`Sale price is not bundle pricing`),i(`p`,null,[e(`The General tab's `),i(`strong`,null,`Sale price`),e(` field is visible for bundle products but is `),i(`strong`,null,`not`),e(` used by the bundle's price calculation. Use the bundle discount to advertise savings.`)])],-1)])}var f=c(u,[[`render`,d]]);export{l as _pageData,f as default};